#pragma once
#include "../port_state.h"
namespace ws2ports {
struct FunctionEnvelope {
 static constexpr ws::Info info{"essentials.function_envelope","Function Envelope",2};
 static constexpr std::array inputs{ws::port("gate","Gate",WS2_GATE)};static constexpr std::array outputs{ws::port("envelope","Envelope",WS2_CV_UNI)};
 static constexpr std::array params{ws::param("rise","Rise",.0001f,30,.01f,"s",port_flags,WS2_LINEAR,0),ws::param("fall","Fall",.0001f,30,.1f,"s",port_flags,WS2_LINEAR,1),ws::param("curve","Curve",-1,1,0,"",port_flags,WS2_LINEAR,2)};
 struct Voice{double level=0,start=0,endpoint=0,rise=.01,fall=.1,curve=0,latched_curve=0;uint64_t length=1,elapsed=1;bool high=false;float last_rise=.01f,last_fall=.1f,last_curve=0;};std::array<Voice,16>voices{};double rate=48000;
 void prepare(const ws::Setup&s){rate=s.sample_rate();reset();}void reset(){for(auto&v:voices){v.level=v.start=v.endpoint=0;v.elapsed=v.length=1;v.high=false;}}
 void process(ws::Block&b){b.out(0).set_channels(b.channels());b.out(0).mark_constant(false);for(uint32_t c=0;c<b.channels();++c){auto&v=voices[c];for(uint32_t i=0;i<b.frames();++i){float rise=b.param(0).value(c,i),fall=b.param(1).value(c,i),curve=b.param(2).value(c,i);if(rise!=v.last_rise){v.rise=rise;v.last_rise=rise;}if(fall!=v.last_fall){v.fall=fall;v.last_fall=fall;}if(curve!=v.last_curve){v.curve=curve;v.last_curve=curve;}float gate=b.in(0).value(c,i);bool high=std::isfinite(gate)&&gate>=.5f;if(high!=v.high){v.high=high;v.start=v.level;v.endpoint=high?1.:0.;v.latched_curve=v.curve;double seconds=high?v.rise:v.fall;v.length=std::max<uint64_t>(1,static_cast<uint64_t>(std::llround(seconds*rate)));v.elapsed=0;}
  if(v.elapsed<v.length){++v.elapsed;if(v.elapsed==v.length)v.level=v.endpoint;else{double u=static_cast<double>(v.elapsed)/static_cast<double>(v.length),k=4.*v.latched_curve;double shaped=k==0.?u:std::expm1(k*u)/std::expm1(k);v.level=v.start+(v.endpoint-v.start)*shaped;}}b.out(0).ch(c)[i]=static_cast<float>(v.level);}}}
 int save_state(ws::Writer w){if(!w.u32(1))return WS2_CAPACITY;for(auto&v:voices){for(double x:{v.level,v.start,v.endpoint,v.rise,v.fall,v.curve,v.latched_curve})if(!write_double(w,x))return WS2_CAPACITY;if(!w.u32(uint32_t(v.length))||!w.u32(uint32_t(v.elapsed))||!w.u32(v.high?1:0)||!w.f32(v.last_rise)||!w.f32(v.last_fall)||!w.f32(v.last_curve))return WS2_CAPACITY;}return WS2_OK;}
 int load_state(ws::Reader r){uint32_t version;if(!r.u32(version))return WS2_INVALID;if(version!=1)return WS2_UNSUPPORTED;auto staged=voices;for(auto&v:staged){for(double*x:{&v.level,&v.start,&v.endpoint,&v.rise,&v.fall,&v.curve,&v.latched_curve})if(!read_double(r,*x))return WS2_INVALID;uint32_t length,elapsed,high;if(!r.u32(length)||!r.u32(elapsed)||!r.u32(high)||!r.f32(v.last_rise)||!r.f32(v.last_fall)||!r.f32(v.last_curve)||!length||length>11520000||elapsed>length||high>1||v.level<0||v.level>1||v.start<0||v.start>1||(v.endpoint!=0&&v.endpoint!=1)||v.rise<double(.0001f)||v.rise>30||v.fall<double(.0001f)||v.fall>30||std::abs(v.curve)>1||std::abs(v.latched_curve)>1||!std::isfinite(v.last_rise)||!std::isfinite(v.last_fall)||!std::isfinite(v.last_curve)||v.last_rise<.0001f||v.last_rise>30||v.last_fall<.0001f||v.last_fall>30||std::abs(v.last_curve)>1)return WS2_INVALID;v.length=length;v.elapsed=elapsed;v.high=high!=0;}voices=staged;return WS2_OK;}
};
}
